program.run:
const listing = thalyx.list("src");
thalyx.assert(listing.ok, "src could not be listed", listing);
const sources = (listing.entries || []).map((entry) => entry.name).filter((name) => name.endsWith(".rs") && name !== "lib.rs").sort();
const touched = [];
for (const name of sources) {
  const path = "src/" + name;
  const source = thalyx.read(path);
  if (source.ok && source.text.includes("old_api")) {
    thalyx.mustWork(thalyx.substitute(path, "old_api", "new_api"), "the substitution in " + path + " did not happen");
    touched.push(name);
  }
}
const seen = thalyx.changed();
thalyx.assert(seen.count === touched.length, "the tree shows " + seen.count + " change(s) and the program made " + touched.length, seen);
const parses = thalyx.validate({ check: "parses" });
if (parses.verdict !== "passed") { return { gave_up: true, why: parses.summary }; }
const left = thalyx.grep("old_api");
thalyx.assert(left.total === 0, "old_api is still somewhere", left);
return { changed: touched, still_there: left.total };
